package com.enterprise.jvm.metaspace;

import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.net.URL;
import java.net.URLClassLoader;

public class MetaspaceLeakSimulator {

    public static void main(String[] args) throws Exception {
        int iterations = 0;
        while (true) {
            // Intentionally creating a new ClassLoader on every iteration
            // simulating an isolated plugin or dynamic module reload mechanism.
            URL[] urls = new URL[]{new URL("file:///nonexistent/path/")};
            URLClassLoader leakingLoader = new URLClassLoader(urls);

            // Dynamically generate a proxy class associated with this unique ClassLoader
            Runnable proxyInstance = (Runnable) Proxy.newProxyInstance(
                leakingLoader,
                new ClassBasedInterface[]{},
                new LeakingInvocationHandler()
            );

            // By failing to dereference 'leakingLoader' and keeping proxies alive,
            // we prevent class unloading and trigger java.lang.OutOfMemoryError: Metaspace
            if (++iterations % 1000 == 0) {
                System.out.println("Loaded proxy batches: " + iterations);
            }
        }
    }

    private interface ClassBasedInterface {}
    private static class LeakingInvocationHandler implements InvocationHandler {
        @Override
        public Object invoke(Object proxy, Method method, Object[] args) { return null; }
    }
}
